import json


print("=== FNF Chart BPM Remap Tool (V-Slice) ===")
# Generated by Grok lol


# === CONFIGURE THESE ===
input_file = "input.json"   # Change if your file has a different name
output_file = "output.json"

old_bpm = 800.0
new_bpm = 1600.0

cutoff = 0          # Only remap notes after this time (ms). Set to 0 to remap everything.
# ========================


try:
    with open(input_file, 'r', encoding='utf-8') as f:
        data = json.load(f)
    
    print(f"Loaded {input_file} successfully!")
    
    if new_bpm <= 0 or old_bpm <= 0:
        raise ValueError("BPM values must be greater than 0")
    
    scale = old_bpm / new_bpm
    print(f"Scaling factor: {old_bpm} → {new_bpm}  (×{scale:.6f})")
    
    modified_count = 0
    is_chart = False
    is_metadata = False

    # --- Chart file: notes ---
    if "notes" in data and isinstance(data["notes"], dict):
        is_chart = True
        print("Detected: Chart file (notes)")
        
        for difficulty, note_list in data["notes"].items():
            if not isinstance(note_list, list):
                continue
                
            for note in note_list:
                if not isinstance(note, dict) or "t" not in note:
                    continue
                    
                if note["t"] > cutoff:
                    # Scale time
                    note["t"] = round(note["t"] * scale, 9)
                    
                    # Scale hold length if present
                    if "l" in note and note["l"] is not None:
                        note["l"] = round(note["l"] * scale, 9)
                    
                    modified_count += 1

    # --- Metadata file: timeChanges ---
    if "timeChanges" in data and isinstance(data["timeChanges"], list):
        is_metadata = True
        print("Detected: Metadata file (timeChanges)")
        
        for tc in data["timeChanges"]:
            if isinstance(tc, dict) and "t" in tc and tc["t"] > cutoff:
                tc["t"] = round(tc["t"] * scale, 9)
                modified_count += 1

    # --- Events (if present) ---
    if "events" in data and isinstance(data["events"], list):
        for event in data["events"]:
            if isinstance(event, dict) and "t" in event and event["t"] > cutoff:
                event["t"] = round(event["t"] * scale, 9)
                modified_count += 1

    if not is_chart and not is_metadata:
        print("⚠️  Warning: Neither 'notes' nor 'timeChanges' found. Nothing was modified.")
    
    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=1)
    
    print(f"\n✅ Success!")
    print(f"   Modified {modified_count} entries")
    print(f"   Output saved to: {output_file}")
    print(f"\nNote: You will also need to change the BPM in the song metadata / chart editor to {new_bpm}.")
    
except FileNotFoundError:
    print(f"❌ Error: Could not find '{input_file}'")
    print("Make sure the script is in the same folder as your JSON file.")
except json.JSONDecodeError as e:
    print("❌ Error: Invalid JSON file")
    print(e)
except Exception as e:
    print("❌ Unexpected error:", e)

print("\nPress Enter to close...")
input()
